fn first_even_odd_indices(lst: Vec<i32>) -> (usize, usize) {
    // We need to find the first even element index i such that
    // all elements before i are odd.
    // And separately, find the first odd element index j such that
    // all elements before j are even.
    //
    // Since array has at least one even and at least one odd element,
    // and length >= 2, both indices exist.

    let mut even_index = None;
    let mut odd_index = None;

    // Find the first even index i where all before i are odd
    // We scan from left to right and keep track of whether
    // all previous elements were odd.
    for (idx, &val) in lst.iter().enumerate() {
        if val % 2 == 0 {
            // Check all elements before idx are odd
            if lst[..idx].iter().all(|x| x % 2 != 0) {
                even_index = Some(idx);
                break;
            }
        }
    }

    // Find the first odd index j where all before j are even
    for (idx, &val) in lst.iter().enumerate() {
        if val % 2 != 0 {
            // Check all elements before idx are even
            if lst[..idx].iter().all(|x| x % 2 == 0) {
                odd_index = Some(idx);
                break;
            }
        }
    }

    // Both indices must exist due to problem assumptions
    (even_index.unwrap(), odd_index.unwrap())
}